import { exp } from "mathjs";

// Step response for first order: y(t) = Vc0 * exp(-t/tau) + K * (1 - exp(-t/tau))
function firstOrderStep({ gain, timeConstant, Vc0 = 0 }, tMax = 10, dt = 0.05) {
  const data = [];
  for (let t = 0; t <= tMax; t += dt) {
    const y = Vc0 * exp(-t / timeConstant) + gain * (1 - exp(-t / timeConstant));
    data.push({ t: parseFloat(t.toFixed(2)), y });
  }
  return data;
}

// Step response for second order (underdamped) with initial conditions:
// y(t) = 1 - (1/√(1-ζ^2)) * exp(-ζωₙt) * sin(ωₙ√(1-ζ^2)t + arccos(ζ))
// For nonzero initial conditions, use standard solution for y(0) and y'(0)
function secondOrderStep({ gain, timeConstant, damping, Vc0 = 0, Il0 = 0, C = 1, wn: wnOverride, zeta: zetaOverride }, tMax = 10, dt = 0.05) {
  const data = [];
  // wn and zeta can be overridden for more accurate mapping
  const wn = wnOverride || 1 / timeConstant;
  const zeta = zetaOverride !== undefined ? zetaOverride : damping;
  // Initial conditions
  const y0 = Vc0; // initial capacitor voltage
  // For a step input, initial derivative (dy/dt) = (Il0/C) if Il0 is initial inductor current
  const dy0 = Il0 / C;
  for (let t = 0; t <= tMax; t += dt) {
    let y;
    if (zeta < 1) {
      // Underdamped
      const wd = wn * Math.sqrt(1 - zeta * zeta);
      // General solution: y(t) = 1 + A*exp(-zeta*wn*t)*cos(wd*t) + B*exp(-zeta*wn*t)*sin(wd*t)
      // A = y0 - 1
      // B = (dy0 + zeta*wn*(1-y0)) / wd
      const A = y0 - gain;
      const B = (dy0 + zeta * wn * (gain - y0)) / wd;
      y = gain + exp(-zeta * wn * t) * (A * Math.cos(wd * t) + B * Math.sin(wd * t));
    } else if (zeta === 1) {
      // Critically damped
      // y(t) = 1 + (A + B*t) * exp(-wn*t)
      const A = y0 - gain;
      const B = dy0 + wn * (gain - y0);
      y = gain + (A + B * t) * exp(-wn * t);
    } else {
      // Overdamped
      // y(t) = 1 + C1*exp(s1*t) + C2*exp(s2*t)
      const s1 = -wn * (zeta - Math.sqrt(zeta * zeta - 1));
      const s2 = -wn * (zeta + Math.sqrt(zeta * zeta - 1));
      // Solve for C1 and C2 using initial conditions
      // y(0) = gain + C1 + C2 = y0
      // y'(0) = C1*s1 + C2*s2 = dy0
      const denom = s1 - s2;
      const C1 = (dy0 - (y0 - gain) * s2) / denom;
      const C2 = ((y0 - gain) * s1 - dy0) / denom;
      y = gain + C1 * exp(s1 * t) + C2 * exp(s2 * t);
    }
    data.push({ t: parseFloat(t.toFixed(2)), y });
  }
  return data;
}

export function getStepResponse(systemType, parameters, tMax = 10, dt = 0.05) {
  if (systemType === "firstOrder") {
    return firstOrderStep(parameters, tMax, dt);
  } else if (systemType === "rlcSeries" || systemType === "rlcParallel") {
    return secondOrderStep(parameters, tMax, dt);
  } else {
    // For unknown, return flat zero for now
    return Array.from({ length: Math.ceil(tMax / dt) + 1 }, (_, i) => ({ t: parseFloat((i * dt).toFixed(2)), y: 0 }));
  }
} 